import std.io
import std.fs

pub fn main() effect io -> Result<(), fs.FsError> {
    match fs.makeDir("reg") {
        Ok(_) => { io.println("mkdir-ok") }
        Err(_) => { io.println("mkdir-bad") }
    }
    match fs.writeFile("reg/d.txt", "d") {
        Ok(_) => { io.println("d-ok") }
        Err(_) => { io.println("d-bad") }
    }
    match fs.writeFile("reg/b.txt", "b") {
        Ok(_) => { io.println("b-ok") }
        Err(_) => { io.println("b-bad") }
    }
    match fs.writeFile("reg/c.txt", "c") {
        Ok(_) => { io.println("c-ok") }
        Err(_) => { io.println("c-bad") }
    }
    match fs.writeFile("reg/a.txt", "a") {
        Ok(_) => { io.println("a-ok") }
        Err(_) => { io.println("a-bad") }
    }
    match fs.listDir("reg") {
        Ok(xs) => {
            var n: Int64 = 0
            for e in xs {
                io.println("entry:${e}")
                n = n + 1
            }
            io.println("count:${n}")
        }
        Err(_) => { io.println("list-bad") }
    }
    return Ok(())
}
